from flask import Flask, jsonify, request
import uuid

app = Flask(__name__)
todos = {}

@app.route('/todos', methods=['GET'])
def list_todos():
    return jsonify(list(todos.values()))

@app.route('/todos', methods=['POST'])
def create_todo():
    data = request.json or {}
    todo_id = str(uuid.uuid4())[:8]
    todo = {'id': todo_id, 'title': data.get('title', 'Untitled'), 'done': False}
    todos[todo_id] = todo
    return jsonify(todo), 201

@app.route('/todos/<todo_id>', methods=['GET'])
def get_todo(todo_id):
    if todo_id not in todos:
        return jsonify({'error': 'not found'}), 404
    return jsonify(todos[todo_id])

@app.route('/todos/<todo_id>', methods=['PATCH'])
def update_todo(todo_id):
    if todo_id not in todos:
        return jsonify({'error': 'not found'}), 404
    data = request.json or {}
    if 'title' in data: todos[todo_id]['title'] = data['title']
    if 'done' in data: todos[todo_id]['done'] = data['done']
    return jsonify(todos[todo_id])

@app.route('/todos/<todo_id>', methods=['DELETE'])
def delete_todo(todo_id):
    todos.pop(todo_id, None)
    return '', 204

if __name__ == '__main__':
    print('TODO API running on http://0.0.0.0:5000')
    print('Endpoints:')
    print('  GET    /todos')
    print('  POST   /todos')
    print('  GET    /todos/<id>')
    print('  PATCH  /todos/<id>')
    print('  DELETE /todos/<id>')
    app.run(host='0.0.0.0', port=5000)
